<?php
require_once dirname(__DIR__).'/includes/auth.php';$u=require_role('examiner');$pid=filter_input(INPUT_GET,'project_id',FILTER_VALIDATE_INT)?:0;if(!project_access($pid,$u)){http_response_code(403);exit('Project is not assigned to your account.');}$err='';
$q=db()->prepare('SELECT p.*,s.id session_id FROM projects p JOIN academic_sessions s ON s.id=p.academic_session_id WHERE p.id=?');$q->execute([$pid]);$project=$q->fetch();$q=db()->prepare('SELECT COUNT(*) FROM submissions WHERE project_id=? AND document_type="final_project" AND status="approved"');$q->execute([$pid]);if(!$project||$project['status']!=="under_evaluation"||!(int)$q->fetchColumn()){http_response_code(404);exit('Evaluation is not available for this project yet.');}$q=db()->prepare('SELECT c.* FROM evaluation_criteria c WHERE c.is_active=1 AND (c.academic_session_id IS NULL OR c.academic_session_id=?) AND (c.department_id IS NULL OR c.department_id=?) AND c.evaluator_role="examiner" ORDER BY c.sort_order,c.id');$q->execute([$project['session_id'],$project['department_id']]);$criteria=$q->fetchAll();
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$comment=post_string('overall_comment',5000);$db=db();try{if(!$criteria)throw new DomainException('This project has no active examiner evaluation criteria. Contact the department HOD.');$db->beginTransaction();$db->prepare('INSERT INTO evaluations(project_id,evaluator_id,evaluator_role,overall_comment,status) VALUES(?,?,"examiner",?,"draft") ON DUPLICATE KEY UPDATE overall_comment=VALUES(overall_comment)')->execute([$pid,$u['id'],$comment]);$q=$db->prepare('SELECT id FROM evaluations WHERE project_id=? AND evaluator_id=?');$q->execute([$pid,$u['id']]);$eid=(int)$q->fetchColumn();$total=0.0;foreach($criteria as $c){$raw=$_POST['score'][$c['id']]??null;if(!is_scalar($raw)||!is_numeric($raw))throw new DomainException('Enter a numeric score for every criterion.');$score=(float)$raw;if($score<0||$score>(float)$c['max_score'])throw new DomainException('Enter a score between zero and the maximum for every criterion.');$total+=$score*(float)$c['weight'];$commentScore=trim((string)($_POST['criterion_comment'][$c['id']]??''));$db->prepare('INSERT INTO evaluation_scores(evaluation_id,criterion_id,score,comment) VALUES(?,?,?,?) ON DUPLICATE KEY UPDATE score=VALUES(score),comment=VALUES(comment)')->execute([$eid,$c['id'],$score,$commentScore?:null]);}$db->prepare('UPDATE evaluations SET total_score=?,status="submitted",submitted_at=NOW() WHERE id=?')->execute([$total,$eid]);$db->prepare('UPDATE project_examiners SET status="submitted" WHERE project_id=? AND examiner_id=?')->execute([$pid,$u['id']]);$db->commit();audit('evaluation_submitted','evaluation',$eid,'Examiner evaluation submitted');$coord=db()->query("SELECT id FROM users WHERE role_id=(SELECT id FROM roles WHERE name='coordinator') AND account_status='active'")->fetchAll(PDO::FETCH_COLUMN);foreach($coord as $cid)notify_user((int)$cid,'Evaluation submitted','An examiner has submitted an evaluation.','action','project',$pid);flash('success','Evaluation submitted.');redirect('examiner/projects.php');}catch(DomainException $e){if($db->inTransaction())$db->rollBack();$err=$e->getMessage();}catch(Throwable $e){if($db->inTransaction())$db->rollBack();error_log($e->getMessage());$err='The evaluation could not be saved.';}}
$q=db()->prepare('SELECT id FROM submissions WHERE project_id=? AND document_type="final_project" ORDER BY submitted_at DESC LIMIT 1');$q->execute([$pid]);$finalSub=(int)$q->fetchColumn();$pageTitle='Project evaluation';require dirname(__DIR__).'/includes/header.php';
?><h2 class="h5"><?= e($project['title']) ?></h2><?php if($finalSub): ?><div class="mb-3"><strong>Final document:</strong> <?php $q=db()->prepare('SELECT id,original_filename FROM submission_versions WHERE submission_id=? ORDER BY version_number DESC LIMIT 1');$q->execute([$finalSub]);$fv=$q->fetch();if($fv): ?><a href="<?= e(url('download.php?version='.(int)$fv['id'])) ?>"><?= e($fv['original_filename']) ?></a><?php endif; ?></div><?php endif; ?><?php if($err): ?><div class="alert alert-danger" role="alert"><?= e($err) ?></div><?php endif; ?><?php if(!$criteria): ?><div class="alert alert-warning" role="status">No active examiner evaluation criteria are configured. Contact the department HOD.</div><?php endif; ?><form method="post" class="card p-4" data-submitting-message="Submitting your evaluation. Please wait."><input type="hidden" name="csrf_token" value="<?= e(csrf_token()) ?>"><?php foreach($criteria as $c): ?><div class="row align-items-end border-bottom py-3"><div class="col-md-6"><label class="form-label fw-semibold"><?= e($c['name']) ?> (max <?= e((string)$c['max_score']) ?>)</label><div class="small text-muted"><?= e($c['description']??'') ?></div></div><div class="col-md-2"><input class="form-control" type="number" name="score[<?= (int)$c['id'] ?>]" aria-label="Score for <?= e($c['name']) ?>" min="0" max="<?= e((string)$c['max_score']) ?>" step="0.01" required></div><div class="col-md-4"><input class="form-control" name="criterion_comment[<?= (int)$c['id'] ?>]" aria-label="Comment for <?= e($c['name']) ?>" placeholder="Optional criterion comment"></div></div><?php endforeach; ?><div class="mt-3"><label class="form-label" for="overall-comment">Overall comments</label><textarea id="overall-comment" class="form-control" name="overall_comment" rows="4"></textarea></div><button class="btn btn-primary mt-3" <?= !$criteria?'disabled':'' ?>>Submit evaluation</button></form><?php require dirname(__DIR__).'/includes/footer.php'; ?>
